"""
Context processors for the family_scheduler project.

This module defines context processors that add variables to the template context.
"""

import logging
from typing import Any

from django.conf import settings
from django.db.models import Q

logger = logging.getLogger(__name__)


def google_places_api_key(request: Any) -> dict[str, Any]:
    """
    Add the Google Places API key to the template context.

    Args:
        request: The HTTP request

    Returns:
        dict: A dictionary containing the Google Places API key
    """
    return {"google_places_api_key": settings.GOOGLE_PLACES_API_KEY}


def pending_invitations_count(request: Any) -> dict[str, Any]:
    """
    Add the count of pending invitations for the current user to the context.

    Args:
        request: The HTTP request

    Returns:
        dict: A dictionary containing the pending invitation count
    """
    if not request.user.is_authenticated:
        return {"pending_invitations_count": 0}

    from users.models import FamilyInvite

    # Safely get user email
    user_email = getattr(request.user, "email", None)
    if not user_email:
        return {"pending_invitations_count": 0}

    # Count invites sent to user's email
    invite_count = FamilyInvite.objects.filter(
        email=user_email, status="PENDING"
    ).count()

    # Count network invites if user has a primary family
    # Safely access profile to avoid RelatedObjectDoesNotExist
    profile = getattr(request.user, "profile", None)
    primary_family = getattr(profile, "primary_family", None) if profile else None

    if primary_family:
        try:
            network_invite_count = FamilyInvite.objects.filter(
                Q(create_meta_group=True) | Q(existing_meta_group__isnull=False),
                family=primary_family,
                status="PENDING",
            ).count()
            invite_count += network_invite_count
        except Exception as e:
            # If the database fields don't exist yet (migrations pending),
            # gracefully skip network invites count
            logger.debug(
                "Unable to count network invites, likely due to pending migrations: %s",
                str(e),
            )

    return {"pending_invitations_count": invite_count}


def frames_navigation(request: Any) -> dict[str, Any]:
    """Expose frame feature rollout state for templates."""

    if not request.user.is_authenticated:
        return {
            "frames_feature_enabled": False,
            "frames_admin_access": False,
        }

    try:
        from frames.feature_flags import frames_feature_flags
        from users.utils import get_user_admin_families
    except Exception:  # pragma: no cover - defensive import guard
        return {
            "frames_feature_enabled": False,
            "frames_admin_access": False,
        }

    frames_enabled = frames_feature_flags.is_enabled(request.user)
    if not frames_enabled:
        return {
            "frames_feature_enabled": False,
            "frames_admin_access": False,
        }

    has_admin_family = get_user_admin_families(request.user).exists()
    return {
        "frames_feature_enabled": frames_enabled,
        "frames_admin_access": has_admin_family,
    }


def _build_clancy_assistant_context(
    request: Any, family_features: dict[str, Any]
) -> tuple[dict[str, Any], str]:
    context: dict[str, Any] = {
        "source_screen": "web_page",
        "family_id": family_features.get("family_id") or None,
        "path": getattr(request, "path", ""),
    }
