            if str(immediate_family.id) == str(settings_obj.family_id):
                immediate_feature_settings = settings_obj
                immediate_helper_agent_name = settings_obj.family.helper_agent_name
            else:
                immediate_family = FamilyGroup.objects.select_related(
                    "feature_settings"
                ).get(id=immediate_family.id)
                immediate_feature_settings = immediate_family.feature_settings
                immediate_helper_agent_name = immediate_family.helper_agent_name
            is_admin = FamilyMembership.objects.filter(
                user=request.user,
                family=immediate_family,
                is_active=True,
                is_admin=True,
            ).exists()
            features["clancy_available"] = bool(
                family_planner_feature_flags.is_enabled(request.user)
                and immediate_feature_settings.agent_enabled
                and (is_admin or request.user.is_staff)
