    except Exception:
        logger.debug("Unable to resolve Clancy navigation state", exc_info=True)

    context, prompt = _build_clancy_assistant_context(request, features)
    payload = {
        "family_features": features,
        "clancy_assistant_context": context,
        "clancy_assistant_prompt": prompt,
    }
    setattr(request, payload_attr, payload)
    return payload


def billing_navigation(request: Any) -> dict[str, Any]:
    """Expose billing nav visibility for templates.

