    Uses per-request caching to avoid repeated DB queries.
    """
    if not request.user.is_authenticated:
        return {"show_billing_nav": False}

    cache_attr = "_billing_nav_is_admin"
    if hasattr(request, cache_attr):
        return {"show_billing_nav": getattr(request, cache_attr)}

    try:
        from users.utils import get_user_admin_families
    except Exception:  # pragma: no cover - defensive import guard
        return {"show_billing_nav": False}

    result = get_user_admin_families(request.user).exists()
    setattr(request, cache_attr, result)
    return {"show_billing_nav": result}
